"""Synthetic pages whose infobox Fandom renders as a portable infobox (made-up values).

The API exposes the rendered infobox as the `infoboxes` page property: a JSON list of
items (data, group, header, image...) with each field's `source` (parameter name) and HTML `value`.
"""

PI_PAGES = {
    # stats generated by Lua: the wikitext has no parameters at all
    "Pulse Rifle": "{{Top|Weapon}}\n{{WeaponInfoboxAutomatic}}\nThe '''Pulse Rifle''' is a balanced rifle.\n"
                   "[[Category:Weapons]]\n",
    # non-English infobox name, preceded by a quote box that the name-based guess mistakes for an infobox
    "Ana": "{{Quote box|quote=Hola|author=Ana|source=Episodio 1|width=30}}\n"
           "{{Personaje\n|nombre = Ana\n|raza   = Saiyan\n|edad   = 30\n|altura = 1,70 m\n}}\n"
           "'''Ana''' es una guerrera.\n[[Category:Personajes]]\n",
}

